'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './contour-lines.css'

export type ContourLinesProps = React.ComponentPropsWithoutRef<'div'> & {
    color?: string
    /** Distance between contour lines in px. */
    spacing?: number
    /** Seconds per drift cycle. */
    speed?: number
    paused?: boolean
}

// Topographic contour rings around a few slowly wandering peaks.
const ContourLines = ({ color = 'rgba(52, 211, 153, 0.35)', spacing = 18, speed = 20, paused = false, className, style, children, ...props }: ContourLinesProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-contour', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-contour-color': color, '--rad-fx-contour-spacing': `${spacing}px`, '--rad-fx-contour-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-contour-layer" aria-hidden="true">
            <span /><span /><span />
        </div>
        <div className="rad-fx-contour-content">{children}</div>
    </div>
}

export default ContourLines

.rad-fx-contour {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-contour-layer {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
}

.rad-fx-contour-content { position: relative; }

.rad-fx-contour[data-state='paused'] .rad-fx-contour-layer,
.rad-fx-contour[data-state='paused'] .rad-fx-contour-layer * { animation-play-state: paused !important; }

.rad-fx-contour-layer span {
    position: absolute;
    width: 90%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: repeating-radial-gradient(
        circle at center,
        transparent 0 calc(var(--rad-fx-contour-spacing, 18px) - 1.5px),
        var(--rad-fx-contour-color) calc(var(--rad-fx-contour-spacing, 18px) - 1.5px) var(--rad-fx-contour-spacing, 18px)
    );
    mask-image: radial-gradient(circle, #000 20%, transparent 70%);
    animation: rad-fx-contour var(--rad-fx-contour-speed, 20s) ease-in-out infinite alternate;
}

.rad-fx-contour-layer span:nth-child(1) { left: -25%; top: -40%; }
.rad-fx-contour-layer span:nth-child(2) { right: -30%; top: -10%; width: 70%; animation-delay: calc(var(--rad-fx-contour-speed, 20s) / -2); }
.rad-fx-contour-layer span:nth-child(3) { left: 20%; bottom: -60%; width: 75%; animation-delay: calc(var(--rad-fx-contour-speed, 20s) / -3); }

@keyframes rad-fx-contour {
    from { transform: translate(0, 0) scale(1); }
    to { transform: translate(6%, 8%) scale(1.12); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-contour-layer span { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-contour-layer span { animation: none; }
